import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

argmax_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cstdint>
#include <stdexcept>

__global__ void argmax_kernel(const float* x, int64_t* out, int N, int D, int M, int dim) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (dim == 1) {
        // We are doing argmax across dimension 1
        // Output shape: [N, M], total threads: N*M
        int total = N * M;
        if (idx < total) {
            int n = idx / M;
            int m = idx % M;

            float max_val = x[n * D * M + 0 * M + m];
            int64_t max_idx = 0;

            for(int d = 1; d < D; d++) {
                float val = x[n * D * M + d * M + m];
                if(val > max_val) {
                    max_val = val;
                    max_idx = d;
                }
            }
            out[idx] = max_idx;
        }
    } else if (dim == 2) {
        // We are doing argmax across dimension 2
        // Output shape: [N, D], total threads: N*D
        int total = N * D;
        if (idx < total) {
            int n = idx / D;
            int d = idx % D;

            float max_val = x[n * D * M + d * M + 0];
            int64_t max_idx = 0;

            for(int m = 1; m < M; m++) {
                float val = x[n * D * M + d * M + m];
                if(val > max_val) {
                    max_val = val;
                    max_idx = m;
                }
            }
            out[idx] = max_idx;
        }
    }
}

torch::Tensor argmax_cuda(torch::Tensor x, int dim) {
    // Only supports 3D input for this example
    TORCH_CHECK(x.dim() == 3, "Input must be a 3D tensor.");
    TORCH_CHECK(dim == 1 || dim == 2, "dim must be 1 or 2 for this custom kernel.");

    auto sizes = x.sizes();
    int N = sizes[0];
    int D = sizes[1];
    int M = sizes[2];

    // Prepare output shape
    c10::IntArrayRef out_sizes;
    if(dim == 1) {
        // argmax across D => shape is [N, M]
        out_sizes = {N, M};
    } else {
        // argmax across M => shape is [N, D]
        out_sizes = {N, D};
    }

    // Create output tensor (dtype = long)
    auto out = torch::empty(out_sizes, x.options().dtype(torch::kLong));

    int total_threads = (dim == 1) ? N * M : N * D;
    const int block_size = 256;
    const int num_blocks = (total_threads + block_size - 1) / block_size;

    argmax_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<int64_t>(),
        N, D, M, dim
    );

    return out;
}
"""

argmax_cpp_source = r"""
torch::Tensor argmax_cuda(torch::Tensor x, int dim);
"""

argmax_module = load_inline(
    name="argmax_module",
    cpp_sources=argmax_cpp_source,
    cuda_sources=argmax_source,
    functions=["argmax_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs argmax using a custom CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.argmax = argmax_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.argmax.argmax_cuda(x, self.dim)
